export function getArtigoBySlug(slug: string): ArtigoTeologico | undefined {
  return artigosTeologicos.find((a) => a.slug === slug);
}

export function getAllArtigoSlugs(): string[] {
  return artigosTeologicos.map((a) => a.slug);
}
